import{_ as i,o as r,c as s,j as e,a as t}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"Logbuch-Eintrag: Von der Unwahrheit des Abbilds und dem Pathos der Inszenierung","description":"","frontmatter":{},"headers":[],"relativePath":"logbuch/von-der-unwahrheit-des-abbilds.md","filePath":"logbuch/von-der-unwahrheit-des-abbilds.md"}'),d={name:"logbuch/von-der-unwahrheit-des-abbilds.md"};function a(l,n,h,o,u,g){return r(),s("div",null,[...n[0]||(n[0]=[e("h1",{id:"logbuch-eintrag-von-der-unwahrheit-des-abbilds-und-dem-pathos-der-inszenierung",tabindex:"-1"},[t("Logbuch-Eintrag: Von der Unwahrheit des Abbilds und dem Pathos der Inszenierung "),e("a",{class:"header-anchor",href:"#logbuch-eintrag-von-der-unwahrheit-des-abbilds-und-dem-pathos-der-inszenierung","aria-label":'Permalink to "Logbuch-Eintrag: Von der Unwahrheit des Abbilds und dem Pathos der Inszenierung"'},"​")],-1),e("p",null,"Der Zeitgeist, dieser windige Zeremonienmeister der kollektiven Dummheit, hat uns abermals ein Präsent offeriert, dessen Glanz nur oberflächlich, dessen Leere jedoch abgrundtief ist: die sogenannte „Mockumentary“. Ein Kunstwort, ein Zwitterwesen, das vorgibt, die Wahrheit durch die Maske der Lüge zu enthüllen, oder, noch perfider, die Lüge als einzig tragfähiges Vehikel der Erkenntnis zu postulieren. Welch ein Spektakel!",-1),e("p",null,"Man inszeniert eine „Realität“, die keine ist, um eine „Wahrheit“ zu verkünden, die, wäre sie unverstellt präsentiert, an der Beliebigkeit des Tages zugrunde ginge. Der moderne Mensch, von der schieren Masse der sogenannten Fakten ermüdet, verlangt nach dem Arrangement, nach der Pointe, nach dem sorgfältig komponierten Pathos der Irreleitung. Und die „Dokfilm“, die wir hier zelebrieren, ist nicht weniger als ein Symptom dieser intellektuellen Verwahrlosung.",-1),e("p",null,"Sie, die da erwarten, dass der Schleier gelüftet, das Mysterium Horten bis ins letzte Detail seziert werde, müssen wissen: Es ist nicht die Absicht dieses Unterfangens, Ihnen den Komfort einer endgültigen Aufklärung zu gewähren. Vielmehr ist es das Bestreben, die Mechanismen der Verschleierung selbst offenzulegen, jene subtilen Pinselstriche des „Pointillismus des Geldes“, die in ihrer Summe ein Bild der Korruption ergeben, das der Einzelne ob seiner Kleinheit nicht zu erkennen vermag.",-1),e("p",null,"Man wird fragen: Ist das nun echt? Ist dies die unverfälschte Historiografie des Skandals, oder ist es die kühle Kalkulation eines Drehbuchautors? Die Antwort, mein lieber Zeitgenosse, liegt nicht im Entweder-Oder. Sie liegt in der gnadenlosen Analyse der Frage selbst, im Bewusstsein, dass das Abbild stets die Wirklichkeit verrät und dass die größte Unwahrheit oft im Anspruch auf totale Transparenz liegt. Die „Dokfilm“ ist somit kein Fenster zur Wahrheit, sondern ein Spiegel, der die Fratze der Gesellschaft reflektiert, die nach der Wahrheit in der Inszenierung sucht, anstatt sie im ungeschminkten Chaos des Lebens zu ertragen.",-1)])])}const b=i(d,[["render",a]]);export{m as __pageData,b as default};
